  async function loadRelations(){state.relLoaded=false;state.aiAvailable=false;state.profs=[];state.profSvc=[];state.aiIds={};try{var t=state.tenant,r=await Promise.all([query(window.sb.from('smyl_professionals').select('id,display_name,active').eq('tenant_id',t).eq('active',true).order('display_name')),query(window.sb.from('smyl_professional_services').select('professional_id,service_id').eq('tenant_id',t))]);state.profs=r[0]||[];state.profSvc=r[1]||[];state.relLoaded=true;}catch(e){state.relLoaded=false;}try{var ai=await query(window.sb.from('smyl_ai_scheduling_services').select('service_id').eq('tenant_id',state.tenant));(ai||[]).forEach(function(x){state.aiIds[x.service_id]=true;});state.aiAvailable=true;}catch(e){state.aiAvailable=false;}}
  function profIdsFor(serviceId){var active={};state.profs.forEach(function(p){active[p.id]=true;});return state.profSvc.filter(function(x){return x.service_id===serviceId&&active[x.professional_id];}).map(function(x){return x.professional_id;});}
