  async function load(force){if(!window.tenantId||state.loading||(state.loaded&&state.tenant===window.tenantId&&!force))return;state.loading=true;state.tenant=window.tenantId;loadingSkeleton(true);try{await capabilities();state.services=await query(window.sb.from('smyl_services').select('*').eq('tenant_id',state.tenant).order('category').order('name'))||[];await loadBranchPrices();await loadRelations();state.loaded=true;notice('');render();}catch(e){loadingSkeleton(false);notice('No se pudo cargar el catálogo: '+(e.message||'error de red'),'error');}finally{state.loading=false;}}
  // Precio por sucursal: el precio base queda en el servicio y aquí solo se guardan las excepciones de cada sede.
  async function loadBranchPrices(){try{state.branches=(await query(window.sb.from('smyl_branches').select('id,name,is_default,active').eq('tenant_id',state.tenant).eq('active',true).order('is_default',{ascending:false}).order('name')))||[];state.branchPrices=(await query(window.sb.from('smyl_service_branch_prices').select('service_id,branch_id,price').eq('tenant_id',state.tenant)))||[];}catch(e){state.branchPrices=[];}}
