    var who=whoOk?'<fieldset class="catalog-who"><legend>Quién lo realiza</legend><div class="catalog-chips">'+state.profs.map(function(p){return '<label class="catalog-chip"><input type="checkbox" name="who" value="'+esc(p.id)+'"'+(chosen.indexOf(p.id)>=0?' checked':'')+'><span>'+esc(p.display_name||'Profesional')+'</span></label>';}).join('')+'</div><small>Solo ellos reciben citas de este servicio, en la Agenda y con el asistente. <button type="button" class="catalog-link" data-who-all>Marcar todos</button></small></fieldset>':'';
    var ai=aiOk?'<label class="catalog-ai-switch"><input type="checkbox" name="ai_offer"'+(existing&&state.aiIds[existing.id]?' checked':'')+'><span><strong>La IA puede ofrecerlo</strong><small>El asistente podrá sugerir horarios de este servicio a los pacientes. Tú confirmas cada cita.</small></span></label>':'';
    return '<div class="wide catalog-avail">'+who+ai+rq+'</div>';
